//! ABI94-only regression. Layouts are explicit; London then uses continuous
//! real Room commands, journal replay, state restoration and all four views.
use crate::{catalog,jc029_tests::envelope,model::*,room::*,unit_support::*};
use serde_json::{json,Value};
struct Trace { name: &'static str, room: RoomEnvelope, initial: Value, steps: Vec<Value> }
impl Trace {
    fn new(name: &'static str,mut game:Game)->Self{game.room_id="610000000000000000000001".into();let room=envelope(&game);let initial=json!({"state":serde_json::to_string(&room).unwrap(),"views":(0..4).map(|s|room.view(s,0)).collect::<Vec<_>>()});Self{name,room,initial,steps:vec![]}}
    fn command(&mut self,seat:usize,action:SessionAction){let state=serde_json::to_string(&self.room).unwrap();let command=RoomCommand{command_id:format!("hidden-shuffle-{}-{}",self.name,self.steps.len()),expected_version:self.room.revision,action};let expected=self.room.transition(seat,Some(command.clone()),0).unwrap();assert!(expected.error_code.is_none(),"{:?}",expected.error_message);assert_eq!(serde_json::to_string(&self.room.replay_events(&expected.journal).unwrap()).unwrap(),expected.state);self.room=RoomEnvelope::from_persisted(&expected.state).unwrap();assert_eq!(serde_json::to_string(&self.room).unwrap(),expected.state);let raw=serde_json::to_string(&self.room.game).unwrap();assert_eq!(serde_json::to_string(&Game::from_persisted(&raw).unwrap()).unwrap(),raw);self.steps.push(json!({"state":state,"seat":seat,"command":command,"serverNowMs":"0","expected":expected,"views":(0..4).map(|s|self.room.view(s,0)).collect::<Vec<_>>()}));}
    fn action(&mut self,seat:usize,action:Action){if let Some(w)=self.room.pacing.window.clone(){let intent=format!("hidden-shuffle-intent-{}",self.steps.len());self.command(seat,SessionAction::BeginResponse{window_id:w.id.clone(),intent_id:intent.clone()});self.command(seat,SessionAction::SubmitResponse{window_id:w.id,intent_id:intent,action});}else{self.command(seat,SessionAction::Game{action});}}
    fn advance(&mut self,accept_london:bool){if let Some(p)=self.room.game.pending.clone(){let selected=if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..} if d.ability.key=="hide-and-mix-win"){if accept_london{vec!["accept".into()]}else{vec![]}}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};self.action(p.seat,Action{choice_id:Some(p.choice.id),selected:Some(selected),..Action::new("choose")});}else if let Some(w)=self.room.pacing.window.clone(){let seat=*w.members.iter().find(|(_,d)|matches!(d,Decision::Undecided{..})).unwrap().0;self.command(seat,SessionAction::PassResponse{window_id:w.id});}else{let seat=(0..4).find(|s|self.room.game.legal_actions(*s).iter().any(|a|a.action.kind=="pass")).unwrap();self.action(seat,Action::new("pass"));}}
    fn until(&mut self,accept:bool,predicate:impl Fn(&Game)->bool){for _ in 0..192{if predicate(&self.room.game){return;}self.advance(accept);}panic!("bounded London win {}",self.name);}
    fn london_win(&mut self,accept:bool){self.until(accept,|g|matches!(&g.pending,Some(p)if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key=="hide-and-mix-win")));let p=self.room.game.pending.clone().unwrap();self.action(p.seat,Action{choice_id:Some(p.choice.id),selected:Some(if accept{vec!["accept".into()]}else{vec![]}),..Action::new("choose")});if accept{self.until(false,|g|!g.stack.iter().any(|s|s.frame.as_ref().is_some_and(|f|f.ability_key=="hide-and-mix-win")));}}
    fn export(&self){if let Ok(dir)=std::env::var("HIDDEN_SHUFFLE_NATIVE_DIR"){std::fs::create_dir_all(&dir).unwrap();let bytes=serde_json::to_vec(&json!({"name":self.name,"scope":"Prepared ABI94 Native layout; continuous real London Room commands, strict restoration/journal replay/four views. Not natural browser acceptance or migration.","catalog":catalog::catalog(),"initial":self.initial,"steps":self.steps})).unwrap();use std::io::Write;std::fs::OpenOptions::new().write(true).create_new(true).open(std::path::Path::new(&dir).join(format!("{}.json",self.name))).unwrap().write_all(&bytes).unwrap();}}
}
fn hidden(g:&mut Game,id:&str,seat:usize,r:usize,locks:u32)->String{let mut c=g.make_card(id,seat);c.face_down=true;c.lock_markers=locks;let id=c.id.clone();g.regions[r].cards.push(c);id}
fn london()->Game{let mut g=Game::new("london-regression".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),8).unwrap();for n in 1..4{g.join(format!("P{n}"),"watchers".into()).unwrap();}for p in &mut g.players{p.ready=true;}g.apply(0,Action::new("start")).unwrap();while g.pending.is_some(){choose(&mut g,vec![]);}for p in &mut g.players{p.hand.clear();p.assets.clear();p.graveyard.clear();}for r in &mut g.regions{r.cards.clear();r.influence=[0,0];}g.first_team=0;if let Some(index)=g.regions.iter().position(|r|r.card.definition=="DQJC110"){g.regions.swap(0,index);}else{let index=g.world.iter().position(|c|c.definition=="DQJC110").unwrap();std::mem::swap(&mut g.regions[0].card,&mut g.world[index]);}assert_eq!(g.regions[0].card.definition,"DQJC110");field(&mut g,"JC086",0);g.regions[0].influence=[3,0];g.begin_window(Window::Before(0,2));g}
fn locks(g:&Game,r:usize,seat:usize)->u32{g.regions[r].cards.iter().filter(|c|c.controller==seat).map(|c|c.lock_markers).sum()}

#[test]
fn hidden_shuffle_existing_hidden_marker_survives_original_shared_helper(){let mut g=game();hidden(&mut g,"JC125",0,1,1);hidden(&mut g,"JC032",0,1,0);restore(&mut g);g.world_hide(None,true);assert_eq!(locks(&g,1,0),1);restore(&mut g);}

#[test]
fn hidden_shuffle_actual_london_win_preserves_marked_hidden_and_keeps_singletons(){let mut g=london();let a=hidden(&mut g,"JC125",0,1,1);let b=hidden(&mut g,"JC032",0,1,0);let ally=hidden(&mut g,"JC125",1,1,2);let mut t=Trace::new("abi94-london-hidden-lock",g);t.london_win(true);assert_eq!(locks(&t.room.game,1,0),1);assert!(t.room.game.board(&a).is_none()&&t.room.game.board(&b).is_none());assert_eq!(t.room.game.board(&ally).unwrap().1.lock_markers,2);assert!(t.room.game.regions[1].cards.iter().all(|c|c.face_down));for seat in [2,3]{assert!(t.room.view(seat,0).regions[1].characters.iter().all(|c|c.card_id.is_none()&&c.text.is_none()));}assert!(!t.steps.is_empty());t.export();}

#[test]
fn hidden_shuffle_actual_london_decline_does_not_mix_or_remove_any_marker(){let mut g=london();let a=hidden(&mut g,"JC125",0,1,1);let b=hidden(&mut g,"JC032",0,1,0);let mut t=Trace::new("abi94-london-declined",g);t.london_win(false);assert_eq!(t.room.game.board(&a).unwrap().1.lock_markers,1);assert!(t.room.game.board(&b).is_some());t.export();}

#[test]
fn hidden_shuffle_actual_london_hides_faceup_roles_clears_their_marks_and_preserves_old_hidden(){let mut g=london();let id=field(&mut g,"JC032",0);let (_,mut card)=g.remove_board(&id).unwrap();card.lock_markers=3;g.regions[1].cards.push(card);hidden(&mut g,"JC125",0,1,2);let mut t=Trace::new("abi94-london-flip-versus-mix",g);t.london_win(true);assert_eq!(locks(&t.room.game,1,0),2);assert!(t.room.game.regions[1].cards.iter().all(|c|c.face_down));assert!(t.room.game.board(&id).is_none());t.export();}

#[test]
fn hidden_shuffle_actual_london_large_u64_seed_and_worm_observation_restore(){let mut g=london();g.seed=9_007_199_254_740_993;g.random=g.seed;for id in ["JC054","JC054"]{let id=field(&mut g,id,0);let (_,c)=g.remove_board(&id).unwrap();g.regions[1].cards.push(c);}hidden(&mut g,"JC125",0,1,1);let mut t=Trace::new("abi94-london-worm-and-u64",g);t.london_win(true);assert_eq!(t.room.game.seed,9_007_199_254_740_993);assert_eq!(locks(&t.room.game,1,0),1);assert_eq!(t.room.game.regions[1].cards.iter().filter(|c|c.definition=="JC054"&&c.face_down).count(),2);t.export();}
